fn solve(n: i8) -> bool {
    // Promote to a wider type so the constants 1000, 100, 10 work without overflow.
    let n = n as i32;

    // Extract each digit
    let d1 = n / 1000;          // thousands
    let d2 = (n / 100) % 10;    // hundreds
    let d3 = (n / 10) % 10;     // tens
    let d4 = n % 10;            // ones

    // Check if the first three are equal, or the last three are equal
    (d1 == d2 && d2 == d3) || (d2 == d3 && d3 == d4)
}

